require "rails_helper"

RSpec.describe Invoices::ReservationBoundary do
  # "Send `Rails.event.notify` named `invoices.reservation_refused` on the refusal, with company_id and invoice_id (customer: \"Emit ... `on_another_invoice` refusals, with `company_id`.\")."
  # The payload carries only scalar ids and the reason: never the holder invoice or request text.
  it "emits the refusal with the refused invoice's company and no other invoice's identity" do
    company = create(:company)
    client = create(:client, company:)
    project = create(:project, client:, billable: true)
    entry_owner = create(:user, current_workspace_id: company.id)
    entry = create(:timesheet_entry, user: entry_owner, project:, bill_status: "unbilled")
    holder = create(:invoice, company:, client:, invoice_number: "HOLD-EVT-SEC")
    create(:invoice_line_item, invoice: holder, timesheet_entry: entry, rate: 100, quantity: 60)
    second = create(:invoice, company:, client:, invoice_number: "SECOND-EVT-SEC")

    received = []
    subscriber = Class.new do
      define_method(:initialize) { |sink| @sink = sink }
      define_method(:emit) { |event| @sink << event if event[:name] == "invoices.reservation_refused" }
    end.new(received)
    Rails.event.subscribe(subscriber)
    begin
      expect {
        create(:invoice_line_item, invoice: second, timesheet_entry: entry, rate: 100, quantity: 60, description: "secret note")
      }.to raise_error(Invoices::OperationErrors::Refused)
    ensure
      Rails.event.unsubscribe(subscriber)
    end

    expect(received.size).to eq(1)
    payload = received.first[:payload].to_h.deep_symbolize_keys
    payload = payload.fetch(:data).to_h.deep_symbolize_keys unless payload.key?(:company_id)
    expect(payload[:company_id]).to eq(company.id)
    expect(payload[:invoice_id]).to eq(second.id)
    expect(payload.to_s).not_to include("HOLD-EVT-SEC")
    expect(payload.to_s).not_to include("secret note")
    expect(payload.except(:company_id, :invoice_id, :reason).values).to all(be_nil)
  end
end

