RSpec.describe Invoices::ReservationBoundary do
  let(:seed_holding_company) { create(:company) }
  let(:seed_holding_client) { create(:client, company: seed_holding_company) }
  let(:seed_holding_project) { create(:project, client: seed_holding_client, billable: true) }
  let(:seed_holding_user) { create(:user, current_workspace_id: seed_holding_company.id) }

  def seed_holding_spec_entry
    create(:timesheet_entry, user: seed_holding_user, project: seed_holding_project, bill_status: "unbilled")
  end

  # "When the row is absent and the line set changes, seed the row from the captured set without sending an operation.
  # That keeps a sent invoice holding an entry after its line is removed."
  it "removing a line from a pre-boundary sent invoice keeps the entry locked and seeds the holding from the pre-change set with no intent" do
    invoice = create(:invoice, company: seed_holding_company, client: seed_holding_client, status: :sent)
    kept_line = create(:invoice_line_item, invoice:, timesheet_entry: seed_holding_spec_entry, rate: 100, quantity: 60)
    removed_line = create(:invoice_line_item, invoice:, timesheet_entry: seed_holding_spec_entry, rate: 100, quantity: 60)
    entries = [kept_line.timesheet_entry, removed_line.timesheet_entry]
    entries.each { |entry| entry.update_columns(locked: true) }
    InvoiceEntryHolding.where(company_id: seed_holding_company.id, invoice_id: invoice.id).delete_all
    intents_before = InvoiceOperationIntent.where(company_id: seed_holding_company.id, invoice_id: invoice.id).count

