require "rails_helper"

RSpec.describe Invoices::ReservationBoundary, committed_data: true do
  # "Send `Rails.event.notify` named `invoices.reservation_refused` on the refusal, with company_id and invoice_id"
  # Scenario: the abort row is redelivered by the worker and the recovery sweep. A refusal counted
  # again on each delivery would inflate the signal, so exactly one event must exist.
  it "emits one refusal event for a refused save even when its abort row is delivered again" do
    company = create(:company)
    client = create(:client, company:)
    owner = create(:user, current_workspace_id: company.id)
    project = create(:project, client:, billable: true)
    entry = create(:timesheet_entry, user: owner, project:, bill_status: "unbilled")
    kept = create(:invoice, company:, client:)
    create(:invoice_line_item, invoice: kept, timesheet_entry: entry, rate: 100, quantity: 60)
    second = create(:invoice, company:, client:)

    events = []
    collector = Object.new
    collector.define_singleton_method(:emit) { |event| events << event if event[:name] == "invoices.reservation_refused" }
    Rails.event.subscribe(collector)
    begin
      expect do
        create(:invoice_line_item, invoice: second, timesheet_entry: entry, rate: 100, quantity: 60)
      end.to raise_error(Invoices::OperationErrors::Refused)

      abort_row = InvoiceOperationOutboxItem.where(company_id: company.id, invoice_id: second.id, kind: "abort").first
      expect(abort_row).to be_present
      DeliverInvoiceOperationJob.perform_now(abort_row.id)
      RecoverInvoiceOperationIntentsJob.perform_now
    ensure
      Rails.event.unsubscribe(collector)
    end

    payloads = events.map do |event|
      payload = event[:payload].to_h.deep_symbolize_keys
      payload.key?(:company_id) ? payload : payload.fetch(:data).to_h.deep_symbolize_keys
    end
    expect(payloads.size).to eq(1)
    expect(payloads.first).to include(company_id: company.id, invoice_id: second.id)
    expect(payloads.first.values).not_to include(kept.id)
  end
end

RSpec.describe Invoices::ReservationBoundary do
  # "A line whose `invoice_id` changes registers both invoices, and additions are flushed before removals."
  # "moving an entry-bearing line to another kept invoice is refused."
  # Scenario: one save both removes the entry from its holder and adds it to another kept invoice.
  # Flushing the removal first would free the entry before the conflict check could see it.
  it "refuses moving an entry-bearing line to another kept draft and leaves both invoices as they were" do
    company = create(:company)
    client = create(:client, company:)
    owner = create(:user, current_workspace_id: company.id)
    project = create(:project, client:, billable: true)
    moved_entry = create(:timesheet_entry, user: owner, project:, bill_status: "unbilled")
    other_entry = create(:timesheet_entry, user: owner, project:, bill_status: "unbilled")
    source = create(:invoice, company:, client:)
    target = create(:invoice, company:, client:)
    line = create(:invoice_line_item, invoice: source, timesheet_entry: moved_entry, rate: 100, quantity: 60)
    create(:invoice_line_item, invoice: target, timesheet_entry: other_entry, rate: 100, quantity: 60)
    source_holding = InvoiceEntryHolding.find_by(company_id: company.id, invoice_id: source.id).attributes
    target_holding = InvoiceEntryHolding.find_by(company_id: company.id, invoice_id: target.id).attributes

    expect do
      InvoiceLineItem.find(line.id).update!(invoice_id: target.id)
    end.to raise_error(Invoices::OperationErrors::Refused)

    expect(line.reload.invoice_id).to eq(source.id)
    expect(moved_entry.reload.locked).to be(true)
    expect(InvoiceEntryHolding.find_by(company_id: company.id, invoice_id: source.id).attributes).to eq(source_holding)
    expect(InvoiceEntryHolding.find_by(company_id: company.id, invoice_id: target.id).attributes).to eq(target_holding)
  end
end

RSpec.describe Invoices::ReservationBoundary do
  let(:boundary_flush_company) { create(:company) }
  let(:boundary_flush_client) { create(:client, company: boundary_flush_company) }
  let(:boundary_flush_project) { create(:project, client: boundary_flush_client, billable: true) }
  let(:boundary_flush_user) { create(:user, current_workspace_id: boundary_flush_company.id) }

  def boundary_flush_entry
    create(:timesheet_entry, user: boundary_flush_user, project: boundary_flush_project, bill_status: "unbilled")
  end

  def boundary_flush_intents(invoice)
    InvoiceOperationIntent.where(company_id: boundary_flush_company.id, invoice_id: invoice.id)
  end

  it "writes one intent for each of two draft invoices created in one transaction" do
    first_entry = boundary_flush_entry
    second_entry = boundary_flush_entry

    invoices = ApplicationRecord.transaction do
      [first_entry, second_entry].map do |entry|
        create(:invoice, company: boundary_flush_company, client: boundary_flush_client,
          invoice_line_items_attributes: [{ name: "Work", date: Date.current, rate: 100, quantity: 60, timesheet_entry_id: entry.id }])
      end
    end

    expect(invoices.map { |invoice| boundary_flush_intents(invoice).count }).to eq([1, 1])
    expect([first_entry, second_entry].map { |entry| entry.reload.locked }).to eq([true, true])
  end

  it "writes one intent when the linked entries of a saved draft line are replaced" do
    old_entry = boundary_flush_entry
    new_entry = boundary_flush_entry
    invoice = create(:invoice, company: boundary_flush_company, client: boundary_flush_client)
    line = create(:invoice_line_item, invoice:, timesheet_entry: nil, rate: 100, quantity: 60)
    create(:invoice_line_item_time_entry, invoice_line_item: line, timesheet_entry: old_entry)

    expect do
      InvoiceLineItem.find(line.id).update!(linked_timesheet_entry_ids: [new_entry.id])
    end.to change { boundary_flush_intents(invoice).count }.by(1)

    expect(boundary_flush_intents(invoice).order(:created_at).last.desired_entry_ids).to include(new_entry.id)
    expect(new_entry.reload.locked).to be(true)
  end

  it "rolls back the line and the seeded holding when the flush fails" do
    held_entry = boundary_flush_entry
    added_entry = boundary_flush_entry
    invoice = create(:invoice, company: boundary_flush_company, client: boundary_flush_client)
    create(:invoice_line_item, invoice:, timesheet_entry: held_entry, rate: 100, quantity: 60)
    InvoiceEntryHolding.where(company_id: boundary_flush_company.id, invoice_id: invoice.id).delete_all
    allow_any_instance_of(Invoices::OperationCoordinator).to receive(:call).and_raise(RuntimeError, "flush failed")

    expect do
      create(:invoice_line_item, invoice:, timesheet_entry: added_entry, rate: 100, quantity: 60)
    end.to raise_error(RuntimeError, "flush failed")

    expect(InvoiceLineItem.where(invoice_id: invoice.id, timesheet_entry_id: added_entry.id)).to be_empty
    expect(InvoiceEntryHolding.where(company_id: boundary_flush_company.id, invoice_id: invoice.id)).to be_empty
    expect(added_entry.reload.locked).to be(false)
  end

  # Moved from the model spec of the method mark_billed replaces.
  it "mark_billed bills the entries the invoice holds and the entries its lines reference" do
    held_only_entry = boundary_flush_entry
    line_entry = boundary_flush_entry
    invoice = create(:invoice, company: boundary_flush_company, client: boundary_flush_client, status: :sent)
    create(:invoice_line_item, invoice:, timesheet_entry: line_entry, rate: 100, quantity: 60)
    InvoiceEntryHolding.create!(
      company_id: boundary_flush_company.id, invoice_id: invoice.id, entry_ids: [held_only_entry.id], disposition: "active"
    )

    described_class.mark_billed(invoice)

    expect([held_only_entry, line_entry].map { |entry| entry.reload.bill_status }).to eq(%w[billed billed])
  end
end
